-- Curated, versioned read-only education suggestions. This is reference data,
-- not an authority for what a user may enter and not an accreditation check.
-- Local implementation only; apply through the separately approved process.
BEGIN;

CREATE TABLE public.education_institution_catalog (
  institution_key text PRIMARY KEY
    CHECK (institution_key ~ '^[a-z0-9_]+$'),
  name_en text,
  name_ar text,
  institution_type text NOT NULL CHECK (institution_type IN (
    'public_university', 'private_university', 'national_university',
    'nonprofit_university',
    'technological_university', 'higher_institute', 'academy'
  )),
  aliases_en text[] NOT NULL DEFAULT '{}',
  aliases_ar text[] NOT NULL DEFAULT '{}',
  source_name text NOT NULL,
  source_url text NOT NULL,
  source_note text NOT NULL,
  source_checked_on date NOT NULL,
  catalog_version integer NOT NULL CHECK (catalog_version = 1),
  CHECK (coalesce(length(btrim(name_en)), 0) > 0 OR
         coalesce(length(btrim(name_ar)), 0) > 0)
);

CREATE UNIQUE INDEX education_institution_catalog_name_en_uq
  ON public.education_institution_catalog (lower(name_en))
  WHERE name_en IS NOT NULL;
CREATE UNIQUE INDEX education_institution_catalog_name_ar_uq
  ON public.education_institution_catalog (name_ar)
  WHERE name_ar IS NOT NULL;
CREATE INDEX education_institution_catalog_type_idx
  ON public.education_institution_catalog (institution_type, institution_key);

ALTER TABLE public.education_institution_catalog ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.education_institution_catalog FROM PUBLIC, anon, authenticated, service_role;
GRANT SELECT ON public.education_institution_catalog TO authenticated;
CREATE POLICY education_institution_catalog_authenticated_read
  ON public.education_institution_catalog
  FOR SELECT TO authenticated
  USING ((SELECT auth.uid()) IS NOT NULL);

COMMENT ON TABLE public.education_institution_catalog IS
  'Versioned, curated suggestions only. Profile institution remains free text; not an exhaustive or accreditation authority.';

