CREATE TABLE public.study_field_catalog (
  field_code text PRIMARY KEY CHECK (field_code ~ '^[0-9]{3,4}$'),
  name_en text NOT NULL CHECK (length(btrim(name_en)) > 0),
  name_ar text NOT NULL CHECK (length(btrim(name_ar)) > 0),
  aliases_en text[] NOT NULL DEFAULT '{}',
  aliases_ar text[] NOT NULL DEFAULT '{}',
  source_name text NOT NULL,
  source_url text NOT NULL,
  source_note text NOT NULL,
  source_checked_on date NOT NULL,
  catalog_version integer NOT NULL CHECK (catalog_version = 1)
);
CREATE INDEX study_field_catalog_name_en_idx ON public.study_field_catalog (lower(name_en));
CREATE INDEX study_field_catalog_name_ar_idx ON public.study_field_catalog (name_ar);
ALTER TABLE public.study_field_catalog ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.study_field_catalog FROM PUBLIC, anon, authenticated, service_role;
GRANT SELECT ON public.study_field_catalog TO authenticated;
CREATE POLICY study_field_catalog_authenticated_read
  ON public.study_field_catalog
  FOR SELECT TO authenticated
  USING ((SELECT auth.uid()) IS NOT NULL);
COMMENT ON TABLE public.study_field_catalog IS
  'Curated common fields mapped to UNESCO ISCED-F 2013; not exhaustive and not a restriction on free-text Profile values.';

